<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$d=body();required($d,['id','name','cost_price','selling_price']);$s=db()->prepare('SELECT user_id,status FROM products WHERE id=?');$s->execute([$d['id']]);$p=$s->fetch();if(!$p)fail('Product not found',404);if($p['user_id']!=$u['id']&&$u['role']!=='admin')fail('Not your product',403);if(!in_array($d['category']??'phone',['phone','laptop','computer','accessory','other'],true)||!in_array($d['condition_status']??'used',['new','used','refurbished'],true))fail('Invalid product category or condition');$q=db()->prepare('UPDATE products SET name=?,brand=?,category=?,cost_price=?,selling_price=?,condition_status=?,description=? WHERE id=?');$q->execute([trim($d['name']),$d['brand']??null,$d['category']??'phone',(float)$d['cost_price'],(float)$d['selling_price'],$d['condition_status']??'used',$d['description']??null,$d['id']]);if(array_key_exists('remove_image_ids',$d)&&is_array($d['remove_image_ids'])){foreach($d['remove_image_ids'] as $imageId){$del=db()->prepare('DELETE FROM product_images WHERE id=? AND product_id=?');$del->execute([(int)$imageId,(int)$d['id']]);}}out(['success'=>true,'message'=>'Product updated']);
